script:
(function () {
  'use strict';
  // Savings with a starting balance and regular deposits whose frequency (f a year) can differ
  // from the compounding frequency (n a year, or continuous).
  //   Effective annual rate: EAR = (1 + r/n)^n - 1, continuous EAR = e^r - 1.
  //   Rate per deposit period: i = (1 + EAR)^(1/f) - 1, so interest accrues on each deposit from
  //   the day it is made at exactly the chosen compounding rate.
  //   End-of-period deposits: B <- B(1 + i) + d;  start-of-period: B <- (B + d)(1 + i).
  //   After deposits stop the balance grows by (1 + EAR) a year.
  // "Extra from compounding within the year" = ending balance - the same plan compounded annually.
  // Verified (scratchpad cu5/tests/csv.test.js): $5,000 + $200/month at 5% compounded monthly for
  // 10 years = closed form P(1+r/12)^120 + d((1+r/12)^120 - 1)/(r/12) = $39,291.50; EAR at 5%:
  // quarterly 5.0945%, daily 5.1267%, continuous 5.1271%; start-of-period = end-of-period x (1 + i)
  // for the deposits; 0% returns the money deposited; extra years multiply by (1 + EAR)^years.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var FREQS = [[0, 'Continuously'], [365, 'Daily'], [12, 'Monthly'], [4, 'Quarterly'], [2, 'Semiannually'], [1, 'Annually']];

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function pct(x, d) { return (x * 100).toFixed(d) + '%'; }

  function ear(r, n) { return n === 0 ? Math.exp(r) - 1 : Math.pow(1 + r / n, n) - 1; }

  function project(start, dep, f, e, years, extra, atStart) {
    var i = Math.pow(1 + e, 1 / f) - 1, b = start, total = start, rows = [];
    for (var y = 1; y <= years + extra; y++) {
      var open = b, put = 0;
      if (y <= years) {
        for (var k = 0; k < f; k++) {
          b = atStart ? (b + dep) * (1 + i) : b * (1 + i) + dep;
          put += dep;
        }
      } else {
        b = b * (1 + e);
      }
      total += put;
      rows.push({ year: y, put: put, interest: b - open - put, total: total, balance: b });
    }
    return { balance: b, deposited: total, rows: rows, perPeriod: i };
  }

  function clear() {
    ['csvBalance', 'csvDeposited', 'csvInterest', 'csvGapMoney', 'csvNominal', 'csvEffective', 'csvGap', 'csvPerDeposit'].forEach(function (id) { set(id, '–'); });
    set('csvNote', '');
    document.getElementById('csvCompare').innerHTML = '';
    document.getElementById('csvSchedule').innerHTML = '';
  }

  function update() {
    var start = num('csvStart'), dep = num('csvDeposit'), rate = num('csvRate'), years = Math.round(num('csvYears')),
        extra = Math.round(num('csvExtra')), f = parseInt(document.getElementById('csvDepFreq').value, 10),
        n = parseInt(document.getElementById('csvCompound').value, 10), atStart = document.getElementById('csvTiming').value === 'start';
    if (isNaN(extra)) extra = 0;
    var error = document.getElementById('csvError');
    var bad = [start, dep, rate, years, f, n].some(isNaN) || start < 0 || dep < 0 || start > 1e12 || dep > 1e10 ||
              rate < 0 || rate > 100 || years < 1 || years > 60 || extra < 0 || extra > 60;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter amounts of $0 or more, a rate from 0 to 100%, 1 to 60 years of deposits and 0 to 60 extra years.';
      clear();
      return;
    }
    var r = rate / 100, e = ear(r, n);
    var res = project(start, dep, f, e, years, extra, atStart);
    var annual = project(start, dep, f, ear(r, 1), years, extra, atStart);
    set('csvBalance', money.format(res.balance));
    set('csvDeposited', money.format(res.deposited));
    set('csvInterest', money.format(res.balance - res.deposited));
    set('csvGapMoney', money.format(res.balance - annual.balance));
    set('csvNominal', pct(r, 3));
    set('csvEffective', pct(e, 4));
    set('csvGap', '+' + ((e - r) * 100).toFixed(4) + ' pts');
    set('csvPerDeposit', pct(res.perPeriod, 4));
    var note = '';
    if (n !== 0 && n < f) note = 'Interest compounds less often than you deposit. The calculator credits each deposit with interest from the day it arrives at the equivalent rate; an account that pays nothing on money deposited between compounding dates would earn slightly less.';
    else if (n !== 0 && n > f) note = 'Interest compounds more often than you deposit, so each deposit is compounded several times before the next one arrives.';
    set('csvNote', note);
    document.getElementById('csvCompare').innerHTML = FREQS.map(function (q) {
      var qe = ear(r, q[0]), qb = project(start, dep, f, qe, years, extra, atStart).balance;
      return '<tr><td>' + q[1] + (q[0] === n ? ' (selected)' : '') + '</td><td>' + pct(qe, 4) + '</td><td>+' + ((qe - r) * 100).toFixed(4) +
             ' pts</td><td>' + money.format(qb) + '</td><td>' + money.format(qb - annual.balance) + '</td></tr>';
    }).join('');
    document.getElementById('csvSchedule').innerHTML = res.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.put) + '</td><td>' + money.format(row.interest) + '</td><td>' +
             money.format(row.total) + '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('csvForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
